    ["Padding"] = "填充",
    ["Party, Raid, and Mythic Raid Group Frame layout, bars, auras, indicators, scope overrides and positions"] = "队伍、Raid 和 Mythic Raid 组框架布局、条形图、光环、指示器、范围覆盖和位置",
