    ["Rows"] = "行数",
    ["Same setting as each unit page > Transparency. It uses this same HP track color; off here means at least one unit frame is off."] = "与每个单元页面相同的设置 > 透明度。它使用相同的 HP 轨道颜色；这里的 off 表示至少有一个单元帧关闭。",
    ["Secret aura (name/fingerprint matched)"] = "秘密光环（名字/fingerprint匹配）",
    ["Select:"] = "选择：",
    ["Set Bar Background Tint to white and enable Custom color in Dark Mode. If black, enable Preserve HP color on all unit frames."] = "将栏背景色调设置为白色，并在深色模式下启用自定义颜色。如果是黑色，请在所有单元框架上启用保留 HP 颜色。",
    ["Slot"] = "插槽",
    ["Some layout changes rebuild frames, while visual changes apply instantly. If needed, close and reopen the menu or reload after large profile/import changes."] = "一些布局更改会重建框架，而视觉更改会立即应用。如果需要，关闭并重新打开菜单或在大型配置文件 /import 更改后重新加载。",
    ["The active profile is saved per character. New characters start on this profile instead of Default."] = "活动档案按角色分别保存。新角色将使用此档案，而不是 Default。",
    ["This layer is off in settings and cannot be shown in preview."] = "该图层在设置中处于关闭状态，无法在预览中显示。",
    ["Type a name here before creating or copying a profile."] = "创建或复制配置文件之前，请在此处键入名称。",
    ["Unit Frame Preview"] = "单位框架预览",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "单元框架状态图标位于每个单元页面上。组框架指示器位于组框架 > 指示器中。",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "使用/msuf打开MSUF2。仪表板还包含重置、支持、配置文件和缩放工具。",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "使用仪表板 > 重置框架移动器的位置。仅当您想要重置、复制、导入或替换配置文件数据时才使用配置文件。",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "使用“全局样式”>“条”来突出显示边框，使用“组框架”>“角色”、“威胁”、“驱散”、“咒语”、“角落”和“突袭标记”指示器。",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "使用“组框架”>“布局”来调整大小和间距，使用“增益”和“减益”来调整光环杂乱，使用“指示器”来调整固定位置状态图标。",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "使用组框架页面：尺寸布局/growth/sorting，条形的健康和文本/text，光环的增益和减益以及状态图标的指示器。",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "使用 MSUF 编辑模式拖动单个单元框。当您需要精确的锚定目标或 X/Y 值时，请使用单位页面 > 锚定。",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "使用 MSUF 编辑模式拖动支持的演员条。每个单元页面上都有每个单元的castbar启用/icon/text选项；共享castbar样式位于全局样式> Castbar中。",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "使用MSUF编辑模式拖动播放器框架。要获得精确的锚点或 X/Y 值，请随后打开“播放器”>“锚定”。",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "使用仪表板比例控件进行菜单比例或 UI 比例。您还可以从 MSUF2 窗口的一角调整其大小。",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "使用单元页面进行每个单元的 Castbar 切换，使用全局样式 > Castbar 进行共享纹理、方向、GCD、文本和中断选项。",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "如果 HP 条褪色使空的生命值区域消失或看起来黑色，请使用此选项。它与颜色保持相同的 HP 轨道颜色。",
    ["Value:"] = "价值：",
    ["View"] = "查看",
    ["Welcome to Class Resources!"] = "欢迎来到课堂资源！",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW 会阻止战斗中一些受保护的帧更改。离开战斗，然后应用布局、锚定、enable/disable、配置文件或受保护的框架更改。",
    ["bottom"] = "底部",
