    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "类资源布局、行为、样式、自动隐藏、独立电源栏和替代法力设置",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "单击要隐藏的图层 - 拖动预览元素 - 箭头微移所选内容",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "框架颜色、class/NPC 颜色、能量颜色、castbar 颜色、光环颜色和游戏颜色设置",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "游戏增强设置，例如战斗文本、十字准线和点击投射行为",
    ["gf_layout"] = "gf_layout",
    ["global castbar behavior, textures, GCD, boss castbar and interrupt indicator settings"] = "全局castbar行为、纹理、GCD、bosscastbar和中断指示器设置",
    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "语言/menu行为、更新节奏、工具提示、Blizzard帧处理、小地图图标、声音和范围淡入淡出设置",
