L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "保留 HP 颜色会在图层淡出启用时保持 HP 填充颜色，并使用“颜色”中的相同 HP 轨道颜色单独绘制缺失生命值。\n\n当 HP 条淡出导致空 HP 区域消失或变黑时，这会有所帮助。启用此选项后，某些自定义材质仍可能显得扁平、偏暗或不同。"
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "将 %s 重置为默认值？\n\n这会为当前配置文件重置 %s。默认值会从当前 MSUF 出厂配置读取，因此未来的默认值更改会自动使用。"
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "将 %s 重置为默认值？\n\n这会将整个当前配置文件“%s”重置为当前 MSUF 出厂默认值。该配置文件中的每个菜单都会受到影响。"
L["Reset Scopes"] = "重置范围"

