L["Added improved on/off switch visuals."] = "新增改进的开关视觉。"
L["Added more Menu2 cards and refined menu structure."] = "新增更多 Menu2 卡片并优化菜单结构。"
L["Added more Menu2 cards to group and unit sections."] = "为团队和单位部分新增更多 Menu2 卡片。"
L["Added new Menu2 search module and improved search/guidance text."] = "新增 Menu2 搜索模块并改进搜索/引导文字。"
L["Added new UI/media assets for switches and rounded/superellipse visuals."] = "新增用于开关和圆角/superellipse 视觉的 UI/媒体资源。"
L["Added raid group number display next to unit names."] = "在单位名称旁新增团队小组编号显示。"
L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "为单位、团队、光环、指示器、条和高级页面新增重设计的 Menu2 卡片布局。"
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "新增圆角框体，并为单位框体、团队框体、条、高亮、覆盖层、吸收和指示器提供按表面控制。"
L["Added rounded mask media for the live unit/group frames and Menu2 preview."] = "为实时单位/团队框体和 Menu2 预览新增圆角遮罩媒体。"
L["Added Rounded Texture controls under Global Style > Bars with per-surface toggles, search coverage, localization, preview support, and a reload prompt."] = "在 全局样式 > 条 下新增圆角材质控制，包含按表面开关、搜索、本地化、预览支持和重载提示。"
