L["Editing %s caps. Use Caps & Icons > Max Buffs = 0 to hide buffs only for this unit; Max Debuffs = 0 hides debuffs."] = "正在编辑 %s 上限。使用 上限与图标 > 最大增益 = 0 可仅隐藏该单位的增益；最大减益 = 0 会隐藏减益。"
