L["EM_HELP_BTN"] = "? 帮助"
L["EM_HELP_BTN_TIP"] = "从编辑模式章节打开\n完整的 MSUF 引导设置。"
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r 切换 Essential Cooldown Manager 的全局锚点。|cff60a5ffAnchor|r 打开锚点选择器；悬停一个命名框架，按住 Ctrl 并左键点击，即可将其作为全局锚点。选择自定义锚点会关闭 CDM。"
L["EM_HELP_COPYTO"] = "在单位和施法条弹窗中，|cff60a5ffCopy To|r 会把当前弹窗的设置复制到另一个目标。单位框架复制会保留目标的位置和锚点设置；施法条复制会保留目标的 X/Y 偏移。"
L["EM_HELP_DRAG"] = "在移动器覆盖层上按住鼠标左键并拖动。实时框架会跟随移动器，覆盖层下方的 X/Y 读数显示当前屏幕偏移。松开按钮即可保存位置。"
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r 会退出编辑模式并保留当前更改。进入战斗也会退出编辑模式。弹窗中按 Escape 会关闭/取消；HUD 的 Exit 按钮是正常退出方式。"
L["EM_HELP_NUDGE"] = "方向键移动当前活动目标。优先级为：选中的预览控制点、打开的施法条弹窗、打开的光环弹窗、当前选中的单位框架。步长：1 像素，Shift = 5 像素，Ctrl = 10 像素，Alt = 当前网格步长。"
L["EM_HELP_OPACITY"] = "滚动 |cff60a5ffBG ##%|r 控件只会改变编辑模式背景覆盖层的不透明度。它不会改变单位框架透明度或保存的框架可见性。"
L["EM_HELP_POPUP"] = "左键点击移动器但不拖动，会打开它的编辑弹窗。单位弹窗可编辑框架大小、位置、文字锚点、分离资源设置，以及复制到单位选项。施法条和光环移动器会打开各自的专用弹窗。"
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r 会在编辑模式中为缺失的目标、焦点、目标的目标、宠物、首领和施法条预览切换占位数据。|cff60a5ffAuras|r 会切换光环预览图标和光环移动器框。"
L["EM_HELP_SNAP"] = "网格是视觉辅助。左键点击 |cff60a5ffGrid ##px|r 可开关网格线；滚动可改变间距。|cff60a5ffSnap|r 是独立功能：启用后，拖动的移动器会吸附到屏幕中心或其他可见移动器的边缘/中心，并显示橙色辅助线。"
L["EM_HELP_TITLE"] = "编辑模式 - 快速参考"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r 和 |cff60a5ffRedo|r 会恢复拖动、微调和弹窗编辑前记录的最近编辑模式更改。|cff60a5ffCancel All|r 会请求确认，恢复进入编辑模式前的快照，然后退出。"
