L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Highlights keep Blizzard icons while allowing MSUF's dispel border, glow, and overlay visuals."] = "暴雪模式让 WoW 放置所选光环类型。MSUF 自定义模式让 MSUF 控制光环大小、增长、位置、过滤和样式。MSUF 驱散高亮会保留暴雪图标，同时允许 MSUF 显示驱散边框、发光和覆盖效果。"
