L["Custom Aura tracking on Unitframes"] = "Unitframes 上的自定义 Aura 跟踪"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "在玩家、目标、焦点和首领框体上最多创建三条自定义栏,填入精确的增益或减益 SpellID,并通过按职业整理的栏位在目标框体上追踪自己的 DoT。"
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "您的 MSUF 框架可以充当带有图标、计时器、持续时间条和全框架色调、边框、发光或脉冲效果的聚焦 WeakAura 式跟踪器。"
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "每个受支持的单位帧三个自定义光环跟踪器、精确的咒语白名单和全帧效果"
L["Build a Custom tracker"] = "构建自定义跟踪器"
L["Aura settings in the right place"] = "光环设置各归其位"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "设置与独立样式现位于对应的单位框体和小队/团队菜单中。外观 > 光环提供扩展的共享样式。"
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "在对应菜单中配置每个框体，再到光环菜单统一设置图标形状、边框、阴影、颜色与间距。"
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "每个框体的光环控制，以及外观 > 光环中的扩展共享样式"
L["Open shared Aura styles"] = "打开共享光环样式"
L["Adaptive Party and Raid layouts"] = "自适应派对和团队布局"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "小队、团队和史诗团队获得了自适应布局与缩放、每条栏位的光环过滤与黑名单、专门的 Dispel Overlay 页面,并且你可以按组别决定由 MSUF 还是暴雪绘制框体。"
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "一套团队配置可以从五人本一路陪你进入团队副本，而且你可以逐列决定哪些光环才允许显示。"
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "自适应队伍布局与缩放、队伍光环过滤与黑名单、Dispel Overlay 页面以及按组别的框体提供方设置"
L["Open Group Layout"] = "开放组布局"
L["New health values and text formats"] = "新的健康值和文本格式"
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "生命值文字可以用更一致的格式显示缩写或完整数值,新的最大生命值损失覆盖层会在单位和队伍框体上标出被降低的最大生命值。"
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "您可以选择紧凑的可读性或精确的数字，而无需放弃已使用的布局。"
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "新的生命值缩写、完整数值、文字格式以及最大生命值损失覆盖层"
L["Open HP Text Editor"] = "打开生命值文本编辑器"
L["More flexible class resources"] = "更灵活的班级资源"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "类资源获得了独立的布局、额外的形状以及更精细的每槽和全状态颜色。"
L["You can move class information where your eyes already are and make important states easier to read."] = "您可以将类信息移动到您的视线所在的位置，并使重要的状态更易于阅读。"
L["detached class resources, new shapes and per-state colors"] = "独立的类资源、新形状和每个状态的颜色"
L["Configure Class Resources"] = "配置类资源"
L["Cast target text"] = "投射目标文本"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "目标、焦点和 Boss 施法栏现在可以通过专用的文本样式显示当前咒语的目标是谁。"
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "您可以识别重要演员的目的地，而无需将注意力从演员栏上移开。"
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "Target、Focus 和 Boss 框架上的投射目标名称及其文本样式"
L["Open Target Cast Bar"] = "打开目标投射栏"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "在使用首次加载操作之前，请查看或跳过仪表板上的发布亮点。"
L["Priority Frames for the units that matter"] = "为最重要的单位准备的优先框体"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "手动固定最多五名队友，或让 MSUF 自动挑选坦克，给他们一条专属条带，战斗中绝不重新排序。"
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "你必须盯着的人在屏幕上始终占据同一个位置，并保留小队或团队的外观和点击施法。"
L["Priority Frames, manual and automatic pinning, and their own placement"] = "优先框体、手动与自动固定，以及它们各自的位置"
L["Set up Priority Frames"] = "设置优先框体"
L["One Colors page with click-to-paint"] = "一个支持点击上色的颜色页面"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "所有颜色集中到一个页面，分为玩家与目标、小队与团队、施法条、光环、能量和职业资源等工作区，每个都有自己的实时预览。"
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "你可以直接在预览中点击元素来上色，而不必寻找对应色块，并能重复使用最近或已保存调色板中的任何颜色。"
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "重建的颜色页面、点击上色预览、调色板和新的取色器"
L["Open the Colors page"] = "打开颜色页面"
L["One 0-30 layer scale for everything"] = "统一的 0-30 层级刻度"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "文本、状态图标、光环、边框、条描边、团队指示器和职业资源全部按同一套 0-30 层级刻度排序。"
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "你可以精确决定谁画在谁前面，任意层级滑块旁的层级总览会一次显示整个叠放顺序。"
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "整个插件通用的 0-30 层级刻度和层级总览"
L["MSUF Edit Mode, rebuilt"] = "重建的 MSUF 编辑模式"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "编辑模式获得了可停靠的工具栏、每个框体上重新设计的快捷弹窗，以及与菜单中表现一致的撤销和重做。"
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "你可以直接在屏幕上移动、缩放和复制框体，并在不重新打开菜单的情况下撤回任何误操作。"
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "重建的编辑模式工具栏、快捷弹窗以及共享的撤销和重做"
