L["Spell Indicators on Group Frames"] = "队伍框体上的 Spell Indicators"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "在小队和团队框体上以图标、方块、条形或数字追踪选定的增益,支持自定义法术列表和角落指示器。"
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "你可以直接在框体上看到缺失或即将到期的外部减伤和关键增益,并获得到期图标发光、生命条高亮和整框特效提示。"
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "带自定义光环列表、角落指示器和到期警告的 Spell Indicators"
