L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "每个单位框体都可以让生命和能量从左到右、从右到左、从下到上或从上到下填充。"
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "竖直或镜像的血条布局成为每个框体的独立选项——目前没有任何其他单位框体插件提供这一功能。"
L["the per-frame Fill Direction control for Health and Power bars"] = "生命与能量条的按框体填充方向设置"
