L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "头像可以吸附在框体上、自由放置,或作为覆盖层绘制在生命条内,并拥有独立尺寸、九点锚定、不透明度和可平移的缩放。"
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "矩形和水印式头像成为可能,Relief 环和随形状变化的边框可以修饰方形、圆形、圆角和菱形头像。"
