L["Skipping the Player frame leaves its layout, text, indicators and aura options unreviewed."] = "跳过播放器框架不会对其布局、文本、指示器和光环选项进行检查。"
L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "跳过“目标”框架将不会检查其布局、文本、指示器和光环选项。"
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "跳过焦点框架不会对其布局、文本、指示器和光环选项进行检查。"
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "跳过宠物框架将不会对其布局、文本、指示器和光环选项进行检查。"
L["Skipping Target of target leaves its layout, text and visibility options unreviewed."] = "跳过目标的目标会保留其布局、文本和可见性选项。"
