L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "跳过组布局不会对帧大小、增长、排序、缩放和锚定进行审查。"
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "跳过组栏会导致生命值、力量、文本、范围和驱散呈现未经审查。"
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "跳过群体光环会使群体增益、减益和法术指示器行为不被审查。"
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "跳过条会留下全局纹理、吸收、轮廓、高光和电源行为而不受审查。"
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "跳过演员栏会使演员外观、文本、授权演员和中断提示未经审查。"
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "跳过颜色不会检查框架、功率、光环、等级、文本和演员栏颜色。"
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "跳过字体不会对全局字体、文本样式、颜色和名称缩写进行审查。"
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "跳过光环造型后，buff/debuff 的大小、冷却时间、堆叠数、持续时间条和排序均未经审查。"
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "跳过杂项会导致语言、菜单行为、启动、工具提示和暴雪框架集成不被审查。"
L["Skipping Class Resources leaves class layout, behavior, style, visibility and alternative power displays unreviewed."] = "跳过课堂资源会使课堂布局、行为、风格、可见性和替代电源显示不被审查。"
L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "跳过游戏玩法会导致战斗计时器、状态行为、类别切换和战斗十字准线未经审查。"
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "跳过配置文件将不检查配置文件管理、专业化分配和导出/import 备份。"
