L["Runs a short castbar for the global cooldown whenever an instant spell triggers it.\n\nThe fill and time text are driven natively by the client from the real (haste-scaled) GCD duration - no per-frame addon work while the bar runs. A real cast, channel or empower always takes priority."] = "当瞬发法术触发公共冷却时，显示一条简短的施法条。\n\n填充和时间文字由客户端根据真实（急速加成后）的公共冷却时长原生驱动，施法条运行期间插件没有逐帧开销。真正的施法、引导或蓄力施法始终优先。"
L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "引导时在玩家施法栏上显示刻度分隔符。\n\n受支持的法术使用其实际的刻度计数，包括受支持的天赋和通道持续时间更改。不受支持的通道保留五个均匀间隔的后备线。自定义通道刻度设置覆盖自动布局。\n\n标记是事件驱动的，并且不添加重复通道轮询。"
L["Class Color (Reaction fallback)"] = "类别颜色（反应后备）"
L["Ready color (kick available)"] = "就绪颜色（可踢）"
L["Not ready color (kick on cooldown)"] = "未准备好颜色（启动冷却）"
L["PvP Flag (War Mode/PvP)"] = "PvP 旗帜（战争模式/PvP）"
L["Abbreviate HP values (K/M)"] = "HP 值缩写 (K/M)"
