L["Open Edit Mode and move Party Frames"] = "打开编辑模式并移动派对框架"
L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "打开“组框架”>“光环”以获取增益/减益滤镜、列表、可见性和布局。对于文本、冷却时间、堆栈和持续时间条，请使用“外观”>“光环”并选择“派对”或“团队”范围。"
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "打开组框架 > 布局。文本、资源栏和范围淡入淡出排列在框架基础和透明度旁边。驱散叠加和减益条纹位于驱散叠加页面。修复预测位于“全局样式”>“条形”>“吸收显示”中。"
L["Open it and choose a different value."] = "打开它并选择不同的值。"
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "打开受影响的 UnitFrame > Auras > Debuffs 并启用本机 Dispellable 规则。对于派对/突袭，请使用“群组框架”>“光环”>“减益效果”。"
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "打开受影响的 UnitFrame > Auras > Debuffs 并使用其特定于框架的 SpellID 黑名单。群组排除直接位于群组框架 > 光环 > 减益中。"
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "打开受影响的 UnitFrame > Auras 并选择 Buffs 或 Debuffs。检查其特定于框架的暴雪过滤器、黑名单、启用状态和图标帽。对于派对/突袭，请使用“群组框架”>“光环”。"
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "打开受影响的 UnitFrame > Auras 以了解可见性、布局、过滤器和黑名单。使用“外观”>“光环”来实现范围感知冷却时间、堆栈、持续时间栏和图标样式。"
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "打开框架并展开光环。 Buffs 和 Debuffs 包含自己的暴雪过滤器和黑名单；自定义 1-3 包含自己的白名单。没有单独的“过滤器”选项卡。"
