-- MSUF FULL CORE MENU SOURCE INVENTORY 2
-- Generated missing non-Assistant core keys for zhCN.
L["+"] = "+"
L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "优先级框架可以自动选择治疗者、DPS、职业或规格吗？"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "优先帧可以自动显示增强诱发器吗？"
L["Can Priority Frames show my co-tank?"] = "优先帧可以显示我的副坦克吗？"
L["Can Priority Frames update during combat?"] = "优先帧可以在战斗中更新吗？"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "检查优先级框架是否已启用、您是否已分组、以及匹配的基础派对或团队框架是否已启用。确认指定的坦克或手动固定的玩家当前位于该组中并且可见插槽未满。保存的缺席玩家不会创建空的占位符，并且在战斗结束后在战斗结束时进行受保护的名单更改。"
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "类颜色和健康梯度是运行时颜色，而不是单个可编辑的样本。"
L["Cleave Training Dummy"] = "劈砍训练假人"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "自定义 1-3 始终按帧存储。此处的图标样式和全帧效果仅发生变化"
L["Disabled or whitelist empty"] = "已禁用或白名单为空"
L["Do Priority Frame pins persist, and what order do they use?"] = "优先帧引脚是否持续存在？它们使用什么顺序？"
L["Do Priority Frames inherit click casting and appearance?"] = "优先框架是否继承点击投射和外观？"
L["Do Priority Frames use polling?"] = "优先级帧是否使用轮询？"
L["Do Priority Frames work in parties and dungeons?"] = "优先框架在队伍和地下城中有效吗？"
L["Done"] = "完成"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "现有的优先级框架在战斗中仍然可用，但魔兽世界保护安全的组框架成员资格和布局更改。任何需要安全刷新的引脚、名单、位置或位置更改都会在战斗结束后应用。在战斗之外更改优先帧键绑定。"
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "遵循 Unitframe 全局着色。样本预览当前的全局条形颜色。"
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "对于优先框架，布局是整个配置文件范围的，而引脚是特定于字符的。可见插槽可以设置为 1 到 5 个。首先自动填充水箱，然后按保存的顺序手动填充；重复的选择出现一次。缺席的已保存玩家会等待该玩家重新加入当前组。"
L["How do I pin or unpin a player in Priority Frames?"] = "如何在优先帧中固定或取消固定玩家？"
L["How do I position Priority Frames?"] = "如何定位优先帧？"
L["How should an Augmentation Evoker use Priority Frames?"] = "增强唤起者应该如何使用优先级框架？"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "继承：此范围遵循共享光环风格。仅当此范围需要不同的文本、滑动、边框或计时器设置时，才启用自定义光环样式。"
L["Live "] = "直播"
L["Live preview is unavailable for this container. Sample mode remains available."] = "此容器无法进行实时预览。采样模式仍然可用。"
L["Live preview updates after combat. Sample mode remains available."] = "战斗后实时预览更新。采样模式仍然可用。"
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "手动固定您想要保持可见的队友以进行监控或点击投射。优先框架并不决定谁应该获得先见之明或黑檀之力。如果您希望继承的优先级框架显示先见之明、黑檀之力、流沙、起泡鳞片或其他配置的效果，请配置组框架 > 光环 > 法术指示器。"
L["Native · "] = "母语·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "不使用连续轮询或 OnUpdate 循环来进行优先级选择。当配置、引脚、组状态或相关单元标识更改需要刷新时，它会解析名册。自动选择会读取魔兽世界分配的坦克角色，并且不会在后台检查每个小组成员的专业。"
L["No live "] = "没有直播"
L["No live member"] = "没有实时会员"
L["No matching aura active"] = "没有激活匹配的光环"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "否。自动选择当前仅使用 WoW 指定的 TANK 角色。治疗者、DPS、职业、专长和支持目标必须使用悬停热键手动固定。这避免了背景检查或轮询并保持选择的确定性。"
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "打开组框架 > 优先级 > 放置。将条带附加到活动派对/突袭容器的右侧、左侧、顶部或底部，或选择自由位置并在编辑模式下使用专用的优先级框架移动器。同一页面控制增长、间距、附件间隙和对齐偏移。"
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "覆盖活动：此范围保持其自己的光环风格。在重置覆盖之前，共享样式更改不会取代它。"
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "优先框架不会自动检测其他玩家的专长。自动选择目前仅支持魔兽世界指定的坦克。使用悬停热键手动固定增强诱发器；优先框架不会选择理想的预知或黑檀之力目标。"
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "优先框架复制自动坦克并手动将当前组成员固定到稳定的额外条带中，而无需将其从正常的派对或突袭框架中移除。在一个政党中，他们继承政党框架；在突袭中，他们继承活跃的突袭或神话突袭框架。他们在派对、突袭和神话突袭中工作，继承活动的组框架点击行为，并需要启用匹配的基础组框架。"
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "共享光环样式是单位帧光环文本、滑动、边框和计时器设置的基线。聚会和突袭是具有自己设置的组框架样式范围。"
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "除了派对/Raid 组框架覆盖之外，纹理是共享的。可以按单位或组范围自定义渐变。"
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "该组范围可以使用自定义纹理和渐变。 Raid 也适用于 Mythic Raid。"
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "该范围可以使用自定义渐变和条形设置。纹理仍然遵循共享。"
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "此范围遵循共享栏设置。当此示波器需要不同的渐变或条形设置时，请在此处打开自定义设置。"
L["Updates after combat"] = "战斗后更新"
L["Where can I request a Priority Frames feature?"] = "我可以在哪里请求优先帧功能？"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "分组时，在“组框架”>“优先级”上设置悬停热键。将鼠标悬停在 MSUF 派对、Raid 或优先框架上，然后按优先框架热键来固定或取消固定该玩家。无法通过输入姓名或在当前组之外添加玩家；已保存的缺席图钉会等待并在该玩家重新加入时重新出现。"
L["Why are my Priority Frames empty or missing?"] = "为什么我的优先框架为空或丢失？"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "是的。包含坦克会自动选择魔兽世界指定角色为坦克的当前组成员，通常包括您和您的副坦克。要仅显示您的共同坦克，请禁用自动坦克并手动固定其他坦克。如果《魔兽世界》没有为该玩家分配 TANK 角色，则手动固定是备用方法。"
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "是的。优先框架继承活动的队伍、团队、或神话团队框架外观，包括配置的条、文本、光环、状态指示器和法术指示器。它们使用相同的 MSUF 点击投射注册和单元行为，因此现有的点击投射绑定也适用于重复的帧。"
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "是的。优先框架适用于聚会、突袭和神话突袭。在队伍或地下城中，他们继承队伍框架；在突袭中，他们继承活跃的突袭或神话突袭设置。它们不会创建单独的条带，并且必须启用匹配的基本派对或团队框架。"
