L["  /msuf load <name> switches profile, /msuf profile <name> saves a new one."] = "  /msuf load <name> 用于切换配置文件，/msuf profile <name> 用于保存新的配置文件。"
L["|cffff0000MSUF:|r Cannot change profiles while in combat."] = "|cffff0000MSUF:|r 战斗中无法切换配置文件。"
L["|cffffcc00MSUF:|r Usage: /msuf load <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r 用法：/msuf load <name>。输入 /msuf profile 可查看列表。"
L["|cffff0000MSUF:|r '%s' matches more than one profile. Type the full name."] = "|cffff0000MSUF:|r '%s' 匹配到多个配置文件。请输入完整名称。"
L["|cffff0000MSUF:|r Unknown profile '%s'. Type /msuf profile to list them."] = "|cffff0000MSUF:|r 未知配置文件 '%s'。输入 /msuf profile 可查看列表。"
L["|cffffd700MSUF:|r Profile '%s' is already active."] = "|cffffd700MSUF:|r 配置文件 '%s' 已经在使用中。"
L["|cffffcc00MSUF:|r Usage: /msuf delete <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r 用法：/msuf delete <name>。输入 /msuf profile 可查看列表。"
L["|cffffcc00MSUF:|r Repeat |cffffff00/msuf delete %s|r to delete that profile for good."] = "|cffffcc00MSUF:|r 再次输入 |cffffff00/msuf delete %s|r 以彻底删除该配置文件。"
L["|cffff0000MSUF:|r Cannot reset a profile while in combat."] = "|cffff0000MSUF:|r 战斗中无法重置配置文件。"
L["|cffffcc00MSUF:|r This resets every setting in profile '%s', not just positions."] = "|cffffcc00MSUF:|r 这会重置配置文件 '%s' 中的所有设置，而不仅仅是位置。"
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default confirm|r to go ahead."] = "|cffffcc00MSUF:|r 输入 |cffffff00/msuf default confirm|r 以继续。"
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default|r first, then confirm it."] = "|cffffcc00MSUF:|r 请先输入 |cffffff00/msuf default|r，然后再确认。"
L["|cffff0000MSUF:|r Unknown frame '%s'. Try player, target, focus, pet, boss or priority."] = "|cffff0000MSUF:|r 未知框体 '%s'。可尝试 player、target、focus、pet、boss 或 priority。"
