--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "始终隐藏"
L["Blizzard Raid Manager"] = "暴雪突袭管理器"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "屏幕左边缘的暴雪标签页，包含准备确认、突袭标记和职责筛选。它是唯一的共享框体，因此该设置对小队、突袭和神话突袭完全相同。"
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "淡出突袭管理器，直到鼠标触碰它。准备确认、突袭标记和职责筛选仍可使用，展开的面板会一直显示，直到你再次将其折叠。"
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "始终让突袭管理器保持不可见且不拦截点击。切换回其他选项即可重新使用它的按钮。"
L["Show on mouseover"] = "鼠标悬停时显示"
L["Automatic"] = "自动"
L["Always visible"] = "始终显示"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "当 MSUF 提供当前的队伍框体时隐藏突袭管理器，其余情况交给魔兽世界处理。MSUF 一直都是这样运作的。"
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "即使启用了 MSUF 队伍框体，也保持突袭管理器可用。如果你仍需要它的准备确认、突袭标记和职责筛选，就选这个。"
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "由小队、突袭和神话突袭共用。「自动」会在 MSUF 提供队伍框体时隐藏该标签页。"
L["MSUF detected %s."] = "MSUF detected %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."
L["Second confirmation for %s."] = "Second confirmation for %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirm only if you want the whole Unit Frame layout to move with your cooldowns."
L["Confirm anchoring"] = "Confirm anchoring"
L["Continue"] = "Continue"
L["Keep independent"] = "Keep independent"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "检测到 %s：全局锚点跟随重要冷却管理器。可在 MSUF 编辑模式中用 Cooldown 将其关闭。"
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "检测到 %s：冷却管理器锚定已关闭。可在 MSUF 编辑模式中用 Cooldown 将其开启。"
L["Cooldown Manager anchoring (%s)"] = "冷却管理器锚定（%s）"
L["Global anchor (%s Anchor)"] = "全局锚点（%s 锚点）"
