L["1:1 shows the configured aura pixel size."] = "1:1 显示已设置的光环像素大小。"
L["Aura Options"] = "光环选项"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "光环选项与光环样式属于此 UnitFrame。全局图标外观：外观 > 光环样式。"
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "低于此数值时，剩余时间可显示一位小数。设为 0 则只显示整秒。"
L["Buff Appearance"] = "增益外观"
L["Debuff Appearance"] = "减益外观"
L["Global Aura Appearance: Buffs"] = "全局光环外观：增益"
L["Global Aura Appearance: Debuffs"] = "全局光环外观：减益"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "计时器颜色由实时单位/小队光环和所有预览共享。图标边框和阴影颜色位于外观 > 光环中，并按光环类型分别设置。"
L["Click to open the setting that enables this layer."] = "点击以打开启用该图层的设置。"
L["Controls native Aura tooltips for Spell Icons only."] = "仅控制法术图标的原生光环工具提示。"
L["Cooldown text format"] = "冷却文本格式"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "复制增益、减益效果、外部防御效果和法术图标的显示方式，包括图标缩放、文本、扫描、持续时间条和排序。光环选项、已追踪的法术图标以及全局外观主题保持不变。"
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "复制小队光环的显示、布局、过滤器、精确与分类黑名单、框体层级和驱散选项。光环样式与全局外观主题保持不变。"
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "复制此 UnitFrame 的光环显示、布局、过滤器、黑名单、自定义光环配置和追踪法术。光环样式与全局外观主题保持不变。"
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "复制此 UnitFrame 的增益、减益效果、自定义光环、玩家防御效果和目标 DoT 的显示方式，包括文本、扫描、图标缩放、持续时间条、临期提醒和整框特效。光环选项与全局外观主题保持不变。"
L["Drag background (%dx)"] = "拖动背景 (%dx)"
L["Drag to move. Arrow keys nudge."] = "拖动以移动。方向键可微调。"
L["EllesmereUI"] = "EllesmereUI"
L["EllesmereUI Unlock Mode"] = "EllesmereUI 解锁模式"
L["Exact X coordinate"] = "精确 X 坐标"
L["Exact Y coordinate"] = "精确 Y 坐标"
L["Fit shows the complete aura layout."] = "适应显示完整的光环布局。"
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "全局外观主题仅按光环类型选择。布局、过滤器、计时器、文本和特效仍在对应的 UnitFrame 或 GroupFrame 中按作用域生效。"
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "个别样式在此处编辑。共享图标主题：外观 > 光环样式。"
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "布局、过滤器、列表以及每个容器专属的样式都保存在各自的框体中。外观 > 光环样式仅管理全局图标主题。"
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "以预览框体的中心为基准测量。正值向右移动。方向键与拖动更新的是同一个位置。"
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "以预览框体的中心为基准测量。正值向上移动。方向键与拖动更新的是同一个位置。"
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "开启（默认）：MSUF 框体会出现在 EllesmereUI 解锁模式中。关闭后可继续使用 MSUF 自带的编辑模式。MSUF 配置文件中的位置始终为准。"
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "打开框体并展开光环。增益和减益效果拥有各自的布局、过滤器、黑名单和样式；自定义 1-3、防御增益和目标 DoT 则提供与其内容相符的选项。"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "打开全局光环图标主题：边框、阴影、颜色、行间距以及原生的玩家武器附魔。此 GroupFrame 的个别样式仍保留在这里。"
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "性能警告 (12.1)：只要光环存在已计算的临期时间窗口，暴雪就可能对每个可见的光环按钮逐帧执行 OnUpdate，而不仅是在显示警告时。仅在你接受战斗中这一潜在高开销时才启用。"
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "在实际的 GroupFrames 上涂上占位色调，便于在没有真实可驱散减益效果时判断覆盖效果。关闭此页面时会自动停用。"
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "在实际的 UnitFrame 上涂上占位色调，便于在没有真实可驱散减益效果时判断覆盖效果。关闭此页面时会自动停用。"
L["Position is controlled by the colored aura handle in Preview."] = "位置由预览中带颜色的光环手柄控制。"
L["Preview position"] = "预览位置"
L["Runtime Preview"] = "实时预览"
L["Runtime Preview: live GroupFrames"] = "实时预览：实际的 GroupFrames"
L["Runtime Preview: live UnitFrame"] = "实时预览：实际的 UnitFrame"
L["Runtime Preview: live UnitFrame (drag)"] = "实时预览：实际的 UnitFrame（拖动）"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "形状、边框和阴影：外观 > 光环样式 > 增益。此处所有选项仍按小队作用域生效。"
L["Shared Aura Style"] = "共享光环样式"
L["Shared Aura Style: Buffs"] = "共享光环样式：增益"
L["Shared Aura Style: Debuffs"] = "共享光环样式：减益效果"
L["Shared Preview - "] = "共享预览 - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "在实际的 UnitFrame 上显示占位符号，让你无需真实减益效果即可将其拖到位置。关闭此页面时会自动停用。"
L["Spell Icon Style"] = "法术图标样式"
L["Spell Icon tooltip"] = "法术图标工具提示"
L["Swipe Direction"] = "扫描方向"
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "此开关仅在载入 EllesmereUI 时显示。关闭后 MSUF 会立即返回自带的编辑模式。"
L["Use - / + or Ctrl + mouse wheel to zoom."] = "使用 - / + 或 Ctrl + 鼠标滚轮进行缩放。"
L["Use EllesmereUI Unlock Mode for MSUF"] = "为 MSUF 使用 EllesmereUI 解锁模式"
L["Use the colored Texture handle in Preview for exact placement."] = "使用预览中带颜色的材质手柄进行精确定位。"
L["Zoom changes only this preview, not your Aura settings."] = "缩放只影响此预览，不会改变你的光环设置。"

