L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "将暴雪的临时武器附魔按钮加入玩家增益容器。这是一项共享设置，使用原生光环流程，不含 MSUF 计时器或 OnUpdate。"
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "添加精选列表中缺失的精确有害光环 ID。该光环仍限于你当前的目标以及由你施放的光环。"
L["Adds one exact buff to this frame's blacklist."] = "将一个精确的增益加入此框体的黑名单。"
L["Adds one exact buff to this group's blacklist."] = "将一个精确的增益加入此小队的黑名单。"
L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "将一个精确的有害光环加入此目标、焦点或首领黑名单。仅当无法协助该单位时，暴雪才会应用任意的 SpellID 过滤。"
