L["Bar Only hides the aura icon. Icon + Bar keeps the icon and draws the duration bar on it."] = "仅条会隐藏光环图标。图标 + 条则保留图标并在其上绘制持续时间条。"
L["Bar keeps the normal statusbar. Follow Player Power mirrors the independent detached Player power shape. Orb uses a single vertical fill."] = "条保持普通状态条。跟随玩家资源会沿用独立分离的玩家资源形状。宝珠使用单一的垂直填充。"
