L["Blocks every aura in the selected curated MSUF set."] = "屏蔽所选 MSUF 精选合集中的所有光环。"
L["Blocks only the selected aura from the curated set."] = "仅屏蔽精选合集中所选的那个光环。"
L["Cancelable Player"] = "可取消（玩家）"
L["Castbar Border"] = "施法条边框"
L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "仅更改分离的玩家资源条。左侧的职业资源形状只更改职业资源。"
L["Class Resource Preview"] = "职业资源预览"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "职业资源与玩家资源沿用现有框体。自定义使用下方滑块。宽度仅在布局刷新时确定。"
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "仅控制第二条生命条的轮廓。条使用四条外边框；形状则使用其固定的边缘材质。0 只会关闭轮廓。"
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "仅控制这条第二生命条。普通玩家框体的生命文本仍然独立。"
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "独立控制此光环行。全局样式 > 杂项下的始终 / 脱离战斗 / 修饰键 / 从不仅影响单位框体和小队框体。光环只沿用所选的暴雪/MSUF 外观与光标位置。"
L["Cooldown swipe direction"] = "冷却扫描方向"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "核心功能，对新配置文件默认启用，对已有配置文件启用一次。即使未启用头像，它也可作为普通的防御增益条使用。关闭后将同时停用条和头像位置显示。"
L["Crowd Control"] = "控制类效果"
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "为正式服 12.0+ 与 12.1 精选的 DoT 光环。追踪仅限于此 UnitFrame 的单位以及由你施放的光环；首领设置分别绑定 boss1 至 boss5。"
L["Custom Spell ID"] = "自定义法术 ID"
L["Dark Border"] = "深色边框"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "默认关闭。只要光环存在已计算的临期时间窗口，暴雪的原生实现就会为每个可见的光环按钮启用逐帧 OnUpdate；这可能在警告显示之前就已开始。"
L["Dispellable by Group"] = "小队可驱散"
L["Dispellable by Me (Raid)"] = "我可驱散（团队）"
L["Dispellable by group"] = "小队可驱散"
L["Down (Single Column)"] = "向下（单列）"
L["Duration bar display"] = "持续时间条显示方式"
L["Duration bar fill mode"] = "持续时间条填充模式"
L["Duration bar position"] = "持续时间条位置"
L["Edge strength of every detached Player power shape, including Bar, Round, Crystal and Orb. 0 disables only that edge."] = "所有分离玩家资源形状的边缘强度，包括条、圆形、水晶和宝珠。0 只会关闭该边缘。"
L["Elapsed / Total"] = "已过 / 总计"
L["Enable defensive buffs"] = "启用防御增益"
L["Enable tracked DoTs"] = "启用追踪 DoT"
L["Enter a Spell ID, paste a spell link, or type a spell name. The visible helpful aura is matched even when its buff ID differs from the cast Spell ID."] = "输入法术 ID、粘贴法术链接或键入法术名称。即使增益 ID 与施放的法术 ID 不同，也能识别出可见的有益光环。"
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs."] = "输入法术 ID、粘贴法术链接或键入法术名称。此白名单追踪精确的法术 ID。"
L["Essential cooldown viewer"] = "核心冷却查看器"
L["Exact aura tracking"] = "精确光环追踪"
L["External Defensive"] = "外部防御"
L["External Defensive Player"] = "外部防御（玩家）"
L["Fill Mode"] = "填充模式"
L["Focus off"] = "焦点关闭"
L["Focus on"] = "焦点开启"
L["Global follows the normal MSUF health color mode. Class Color forces your class color. Dark Mode forces the configured dark bar color. HP Gradient colors only this second HP bar by current health."] = "Global 沿用 MSUF 普通的生命颜色模式。Class Color 强制使用你的职业颜色。Dark Mode 强制使用已设置的深色条颜色。HP Gradient 仅按当前生命值为这条第二生命条着色。"
