L["HP Color"] = "生命颜色"
L["HP Outline"] = "生命轮廓"
L["HP Shape"] = "生命条形状"
L["HP only"] = "仅生命"
L["Healers only"] = "仅治疗"
L["Hide permanent auras"] = "隐藏永久光环"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "在目标 DoT 启用期间，将此作用域所选的 DoT 法术 ID 从同一 UnitFrame 的普通减益容器中隐藏。暴雪的黑名单基于 SpellID，因此其他玩家施放的同一法术也会一并隐藏。"
L["Highest priority only"] = "仅最高优先级"
L["Icon Border & Shadow"] = "图标边框与阴影"
L["Include Nameplate-only"] = "包含仅姓名板"
L["Inside Left"] = "内侧左"
L["Inside Right"] = "内侧右"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "让分离的玩家资源保持附着于职业资源条。此连接处于启用状态时，玩家资源的选项将被禁用。"
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "将已设置的头像尺寸与位置保留为隐形锚点，使防御图标能在头像本身关闭时仍留在该处。"
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "将已设置的头像尺寸、位置与形状保留为隐形锚点，供追踪 DoT 在头像本身关闭时使用。"
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "将头像处同时显示的 DoT 图标限制为 1 至 8 个。多出的图标会按此 DoT 行所设的增长方向向外排列。"
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "将头像处同时显示的防御图标数量限制为 1 至 8 个。已有配置文件在更改此数值前将保持为 1。"
L["Lists every MSUF slash command in chat, diagnostics included."] = "在聊天框中列出所有 MSUF 斜杠命令，包含诊断命令。"
L["Max portrait icons"] = "头像图标上限"
L["Maximum debuff duration"] = "最长减益持续时间"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "同时移动分离玩家资源的所有文本槽位。下方的槽位 X/Y 选项可添加各自的偏移。"
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "将玩家资源条移出单位框体。锚定会将其连接到职业资源堆叠；同步则只跟随堆叠的宽度。"
