L["Blizzard Buff & Debuff Frames"] = "暴雪增益与减益框体"
L["Hide Blizzard Buff and Debuff Frames"] = "隐藏暴雪增益与减益框体"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "仅隐藏小地图附近的暴雪玩家增益框体和普通减益图标。私密光环与致命减益警告仍会显示。"
L["Buffs hidden"] = "增益已隐藏"
L["Buffs visible"] = "增益可见"
L["Debuffs hidden"] = "减益已隐藏"
L["Debuffs visible"] = "减益可见"
L["Hide Blizzard Buff Frame"] = "隐藏暴雪增益框体"
L["Hide Blizzard Debuff Frame"] = "隐藏暴雪减益框体"
L["Hides Blizzard's player Buff Frame near the minimap."] = "隐藏小地图附近的暴雪玩家增益框体。"
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "仅隐藏小地图附近的暴雪普通减益图标。私密光环与致命减益警告仍会显示。"
L["Native size"] = "原生尺寸"
L["Native stealable marker"] = "原生可偷取标记"
L["Native weapon enchant auras"] = "原生武器附魔光环"
L["No roles"] = "无职责"
L["No width limit"] = "无宽度限制"
L["Not Cancelable"] = "不可取消"
L["Not Cancelable Player"] = "不可取消（玩家）"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "关闭时显示任意持续时间的减益效果。否则将隐藏总持续时间超过该秒数的减益效果。"
L["One per dispel type"] = "每种驱散类型一个"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "打开全局光环图标主题：边框、阴影、颜色、行间距以及原生的玩家武器附魔。此框体的容器样式仍保留在这里。"
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "为这条第二生命条提供可选的插值。关闭时保持直接的原生 SetValue 更新。"
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "可选的呈现方式；防御增益功能本身并不需要头像。启用头像时，第一个图标会占据头像。头像关闭时，请启用下方的位置选项以将图标保留在该处；否则 MSUF 会安全地回退到普通防御条。"
L["Orb Size"] = "宝珠大小"
L["Pandemic Warning & Style"] = "临期警告与样式"
L["Pandemic color"] = "临期颜色"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "将玩家资源文本放置在分离的资源条上。关闭时，同一文本仍按普通文本布局定位。"
L["Places the duration bar at the top or bottom edge of the aura slot."] = "将持续时间条放置在光环槽位的上边缘或下边缘。"
L["Player Text Outline"] = "玩家文本轮廓"
L["Power Bar Outline"] = "资源条轮廓"
L["Power Text On Bar"] = "条上的资源文本"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "资源锚点在玩家资源条可见时使用它；否则生命条将回退到职业资源锚点。"
L["Raid In Combat"] = "团队战斗中"
L["Raid In Combat Player"] = "团队战斗中（玩家）"
L["Raid Player"] = "团队（玩家）"
L["Remaining / Total"] = "剩余 / 总计"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "剩余会随着光环到期而缩短。已过则会一直增长直到光环到期。"
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "低于此数值时，剩余时间会使用一位小数。计时器在不足 1 分钟时显示不带单位的秒数，超过时显示本地化的分钟。设为 0 则只显示整秒。"
L["Remove from blacklist"] = "从黑名单移除"
L["Remove from whitelist"] = "从白名单移除"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "绘制第二条原生的玩家生命条。普通玩家框体的生命条不受影响，因此你可以显示两次生命值。"
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "以头像大小的图标取代普通 DoT 行。第一个图标会完全沿用此框体头像的宽度、高度与形状。"
L["Runs /msuf reset for frame positions and visibility."] = "对框体位置与显示状态执行 /msuf reset。"
L["Second Player HP Bar"] = "第二条玩家生命条"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "设置分离资源文本所使用的玩家字体作用域。玩家名称与生命文本共用此轮廓设置。"
L["Show DoTs at portrait position"] = "在头像位置显示 DoT"
L["Show buffs at portrait position"] = "在头像位置显示增益"
L["Show cooldown text on portrait"] = "在头像上显示冷却文本"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "在头像图标上显示当前防御增益的剩余持续时间。暴雪会以原生方式更新该文本。"
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "在下方显示所选职业/专精的资源，不会更改你的角色、专精或已保存的设置。"
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "在头像图标上显示所追踪 DoT 的剩余持续时间。暴雪会以原生方式更新该持续时间。"
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "当分离资源由职业资源管理时，可用于玩家资源文本的简单预设。自定义槽位表示在你选择预设之前将保留现有的槽位布局。"
L["Smooth Fill"] = "平滑填充"
L["Spell Text"] = "法术文本"
L["Stops blocking this aura."] = "停止屏蔽此光环。"
L["Sync Width"] = "同步宽度"
L["Tanks only"] = "仅坦克"
L["Target DoT"] = "目标 DoT"
L["Target off"] = "目标关闭"
L["Target on"] = "目标开启"
L["Time Text"] = "时间文本"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "追踪此预设的防御增益。该设置同时适用于防御条和可选的头像图标。"
L["Tracked buffs viewer"] = "追踪增益查看器"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "在此 UnitFrame 的单位上追踪你所选的有害光环。首领框体使用各自的 boss1 至 boss5 单位标识。"
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "为此框体开启或关闭暴雪标记过滤器。首次更改会自动创建框体专属规则；已迁移的共享规则在编辑前仍保持共享。"
L["Unavailable cast fill"] = "不可用施法填充"
L["Up (Single Column)"] = "向上（单列）"
L["Use Player HP Text"] = "使用玩家生命文本"
L["Use portrait position while portrait is off"] = "头像关闭时使用头像位置"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "仅当此生命条明确设为宝珠时才会使用。跟随玩家资源则改为继承玩家资源的宝珠大小。"
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "使用暴雪 12.1 AuraButton 的可偷取过滤器。不会新增任何 MSUF 光环扫描、计时器或 OnUpdate。"
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "使用玩家生命文本设置，并在已绘制的玩家生命文本为最新时直接复制。局部文本 X/Y 仍属于此条。"
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "为分离的玩家资源使用职业资源的宽度，同时不让职业资源接管玩家资源的选项。"
L["Utility cooldown viewer"] = "辅助冷却查看器"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "位于已填充生命值的后方。生命值为 100% 时填充会覆盖背景；轮廓设为 0 也不会关闭此材质。"
L["Weapon Enchants Off"] = "武器附魔关闭"
L["Weapon Enchants On"] = "武器附魔开启"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "只要防御条或头像图标处于启用状态，就会将所有已启用的追踪防御从玩家的普通增益行中隐藏。已停用的防御条目仍会显示在那里。"
L["Whole frame"] = "整个框体"
L["Width Mode"] = "宽度模式"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "条背景色调 深色模式自定义颜色 背景 底纹 bg 不透明度 alpha background backdrop"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "框架基础 启用 加载条件 透明度 距离淡出 玩家 目标 焦点 宠物 消失 不可见"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "框架基础 平滑填充 资源条 平滑填充 生命动画 资源动画 smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "常规 使用 MSUF 小队框体 若此开关关闭 启用 禁用 关闭 隐藏 团队 小队 史诗"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "小队/团队框体 布局 生命平滑填充 生命文本 资源条 平滑填充 小队 团队 smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "小队/团队框体 布局 透明度 不透明度 淡出 目标 战斗中 脱离战斗 alpha 整个框体 状态条 生命 背景 生命填充 生命轨道 保留生命颜色"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "MSUF 编辑模式可移动框体和受支持的施法条。光环图标的位置在各单位页面 > 光环或小队/团队框体 > 光环中设置。"
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "杂项 全局样式 语言 菜单行为 启动提示 工具提示 暴雪框体 小地图 声音"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "姓名缩写 为此作用域使用自定义设置 覆盖 小队 团队 小队框体姓名截断 字体覆盖 共享更改"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "打开外观 > 光环，设置按作用域生效的冷却文本、层数文本、扫描和持续时间条样式。计时器颜色仍位于颜色 > 光环。"
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "打开首领框架 > 光环 > 减益效果。SpellID 黑名单条目、暴雪过滤器、位置和预览都集中在那里；样式仍位于外观 > 光环。"
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "打开全局样式 > 杂项 > 单位框体工具提示，以控制 MSUF 单位框体和小队框体工具提示的来源、锚点、显示模式和修饰键。"
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "打开全局样式 > 杂项，设置语言、菜单行为、启动提示、工具提示、暴雪框体、小地图图标和声音。"
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "打开小队/团队框体 > 布局 > 距离淡出。影响对象可选择淡出框体或生命值，alpha 滑块则控制超出距离和离线时的不透明度。"
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "打开小队/团队框体 > 布局 > 透明度。不透明度控制战斗中与脱离战斗的 alpha；淡出目标可选择整个框体、状态条、生命值或背景。背景与生命图层设置基础颜色、生命填充和生命轨道的不透明度。"
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "打开小队/团队框体 > 布局中的生命平滑填充。若要设置小队框体的资源条，请打开小队/团队框体 > 布局 > 资源栏 > 平滑填充。"
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "打开小队/团队框体 > 布局，在顶部选择小队、团队或史诗，然后关闭使用 MSUF 小队框体。通过若此开关关闭可选择暴雪框体是正常显示，还是两套框体系统都保持隐藏。"
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "打开小队/团队框体 > 布局。框架基础与排序控制玩家和自身的显示，以及玩家单位在小队框体中的排列顺序。"
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "打开小队/团队框体 > 布局。框架基础/布局控制宽度、高度、间距、列数和增长方向；帧缩放控制缩放行为。"
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "打开小队/团队框体 > 状态和指标，设置状态图标、职责/队长/助理、准备确认、焦点光效以及其他小队框体状态指示。"
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "打开玩家 > 光环，然后关闭该玩家框体的增益。按作用域生效的文本和冷却样式仍位于外观 > 光环。"
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "打开某个单位页面，然后使用距离淡出。它适用于目标、目标的目标、焦点、焦点的目标、宠物和首领。"
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "打开受影响的 UnitFrame > 光环，设置图标大小、位置和过滤器。按作用域生效的文本和冷却样式请使用外观 > 光环。"
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "打开受影响的 UnitFrame > 光环或小队/团队框体 > 光环，减少可见数量、计时器文本或不必要的原生过滤规则。"
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "打开受影响的 UnitFrame > 光环，选择增益或减益效果，然后调整过滤器、图标大小、行数、上限和间距。小队/团队的设置位于小队/团队框体 > 光环。"
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "打开单位页面 > 光环或光环位置弹窗来放置单位框体的光环。增益/减益图标属于光环布局设置，不通过 MSUF 编辑模式移动。"
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "距离淡出 小队框体 距离检测 团队距离检测 小队距离检测 超出距离 alpha 离线不透明度 影响 框体 生命"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "距离淡出 单位框体 距离检测 距离检查 超出距离 距离 alpha 距离淡出 目标 目标的目标 焦点 焦点的目标 宠物 首领"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "圆角材质 圆角框体材质 单位框体 小队框体 资源条 鼠标悬停高亮 圆角框体 圆角"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "状态图标 指示器 等级 已启用 附着点 X 偏移 Y 偏移 大小 图层 等级文本 等级指示 玩家等级 目标等级"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "文本 附着点 偏移 字体大小 图层 绘制顺序 间距 分离间距 重叠 状态条 肖像 状态图标"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "使用小队/团队框体 > 布局设置框体大小和间距，使用光环设置增益/减益的位置，使用状态和指标设置固定位置的状态图标。"
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "使用小队/团队框体的各个页面：布局设置大小、增长、排序、状态条和文本；光环设置增益/减益的位置；状态和指标设置状态图标。"
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "使用单位页面设置各单位的施法条开关，使用全局样式 > 施法条设置共享的材质、方向、文本和打断选项。"
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "欢迎使用职业资源！\n\n是否自动设置一条分离的职业条，\n并将其放置在你的核心冷却上方？\n\n此操作将一键配置职业资源的显示、\n锚定、宽度匹配以及分离的玩家资源。\n\n你随后随时可以通过下方的\n|cff00ff00快速设置：职业条|r 按钮再次运行。"
L["External Edit Mode"] = "External Edit Mode"
L["Show Grid2 in MSUF Edit Mode"] = "Show Grid2 in MSUF Edit Mode"
L["Grid2 Edit Mode integration"] = "Grid2 Edit Mode integration"
L["On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."] = "On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."
L["Show Details! in MSUF Edit Mode"] = "Show Details! in MSUF Edit Mode"
L["Details! Edit Mode integration"] = "Details! Edit Mode integration"
L["On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."] = "On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."
L["Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."] = "Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."

