-- Menu localization pass 2026-08-06 (part 7): entries that were still identity English.
L["Confirm anchoring"] = "确认锚定"
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "只有当你希望整个单位框体布局随冷却一起移动时才确认。"
