L["MSUF detected %s."] = "MSUF 检测到 %s。"
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF 现在会将全局单位框体布局锚定到 Essential Cooldown Manager。"
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "在下一步再次确认之前不会移动任何内容。若选择保持独立，你随时可以在 MSUF 编辑模式或 MSUF 菜单的单位 > 锚定中启用 CDM 锚定。"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "在下一步再次确认之前不会移动任何内容。你稍后可以在 MSUF 编辑模式中更改。"
L["Second confirmation for %s."] = "%s 的第二次确认。"
